static int skip(int t){int end=tokens[t].end;t++;while((size_t)t<ntokens&&tokens[t].start<end)t++;return t;}
static unsigned hex4(const char *s){unsigned n=0;for(int k=0;k<4;k++){char c=s[k];n=n*16+(isdigit((unsigned char)c)?c-'0':tolower((unsigned char)c)-'a'+10);}return n;}
