static int field(int obj,const char *name,int required){int found=-1;if(tokens[obj].kind!='{')invalid("object required");for(int k=obj+1;(size_t)k<ntokens&&tokens[k].start<tokens[obj].end;k=skip(skip(k))){char *key=strval(k);if(!strcmp(key,name)){if(found!=-1)invalid("duplicate field");found=k+1;}free(key);}if(found<0&&required)invalid(name);return found;}
