static int ascent_write_data(void){if(!ascent_entries)invalid("inventory required");head_flags=0;int err=write_inventory_dir(0,UBIFS_ROOT_INO);if(err)return err;for(size_t i=0;i<ascent_count;i++)if(!ascent_entries[i].visited)invalid("unvisited inode");return flush_nodes();}
